#include "sleela/compiler.hpp"
#include <iostream>
#include <string>
namespace{void usage(){std::cout<<"SLeeLa Native Compiler "<<sleela::compiler::version<<"\nUsage: sleelac [--check|--run|--emit-ir|--emit-bytecode FILE] SOURCE.sleela\n";}}
int main(int argc,char**argv){if(argc<2){usage();return 2;}std::string mode="--run",src,out;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--help"||a=="-h"){usage();return 0;}if(a=="--check"||a=="--run"||a=="--emit-ir"){mode=a;continue;}if(a=="--emit-bytecode"){if(++i>=argc){std::cerr<<"missing bytecode path\n";return 2;}mode=a;out=argv[i];continue;}if(!a.empty()&&a[0]=='-'){std::cerr<<"unknown option: "<<a<<'\n';return 2;}if(!src.empty()){std::cerr<<"only one source file is accepted\n";return 2;}src=a;}if(src.empty()){usage();return 2;}std::string err;auto text=sleela::compiler::read_text_file(src,err);if(!err.empty()){std::cerr<<err<<'\n';return 1;}auto p=sleela::compiler::compile(text);if(!p.ok()){for(const auto&d:p.diagnostics)std::cerr<<src<<':'<<d.line<<':'<<d.column<<": error: "<<d.message<<'\n';return 1;}if(mode=="--check"){std::cout<<"syntax and semantic checks passed\n";return 0;}if(mode=="--emit-ir"){std::cout<<sleela::compiler::disassemble(p);return 0;}if(mode=="--emit-bytecode"){if(!sleela::compiler::write_bytecode(p,out,err)){std::cerr<<err<<'\n';return 1;}return 0;}auto r=sleela::compiler::run(p);if(!r.ok()){std::cerr<<"runtime error: "<<r.error<<'\n';return 1;}for(auto n:r.printed_values)std::cout<<n<<'\n';return static_cast<int>(r.return_value&255);}
